-- IPA source-reviewed 2021 business and strategy questions, plus an identical public question.
INSERT OR IGNORE INTO questions (id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language,exam_section,exam_section_method,question_kind,exam_origin) VALUES
('fe-exempt-2021-20210613-q61','exam-fe','バランススコアカード','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問61・改編】IT投資評価でバランススコアカードを用いる手法はどれか。','[{"id":"a","text":"キャッシュフローの正味現在価値を使って投資案件を比較する"},{"id":"b","text":"性質やリスク別に投資を分類しカテゴリごとの投資割合を評価する"},{"id":"c","text":"財務・顧客・内部業務など複数視点で指標を設定し経営戦略との適合性を評価する"},{"id":"d","text":"オプション価格付け理論を使って将来の収益やリスクを評価する"}]','"c"','バランススコアカードは複数の視点を用いて戦略に沿った業績を評価する。 中文：平衡计分卡从财务、客户、内部流程等多个视角评价战略绩效。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q62','exam-fe','BPO','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問62・改編】BPOの説明はどれか。','[{"id":"a","text":"外部企業のサーバ処理能力や記憶容量を借りてシステムを運用する"},{"id":"b","text":"外部業者のソフトウェア機能をネットワーク経由で利用する"},{"id":"c","text":"管理部門やコールセンタなどの業務プロセス全般をシステム運用と一体で外部専門業者へ委託する"},{"id":"d","text":"派遣会社の社員を活用しソフトウェア開発費用を低減する"}]','"c"','BPOは業務プロセスの運用を外部専門業者に委託すること。単なるサーバやソフト利用、派遣とは異なる。 中文：BPO将业务流程整体委托给专业外部服务商。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q64','exam-fe','UMLアクティビティ図','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問64・改編】UMLでビジネスプロセスの実行順序や条件分岐などのワークフローを表せる図はどれか。','[{"id":"a","text":"アクティビティ図"},{"id":"b","text":"オブジェクト図"},{"id":"c","text":"クラス図"},{"id":"d","text":"コンポーネント図"}]','"a"','アクティビティ図は処理の流れや分岐・並行を表す。 中文：活动图用于表达流程、分支与并行。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q65','exam-fe','CSR調達','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問65・改編】CSR調達に該当するものはどれか。','[{"id":"a","text":"コスト最小化のため最安価な製品を選ぶ"},{"id":"b","text":"災害に備えて複数の調達先を確保する"},{"id":"c","text":"自然環境や人権への配慮を調達基準として取引先に遵守を求める"},{"id":"d","text":"EDIを利用して迅速かつ正確に購買する"}]','"c"','CSR調達は環境・人権など社会的責任への配慮を調達にも反映する。 中文：CSR采购将环境、人权等社会责任纳入供应商标准。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q66','exam-fe','SWOT外部要因','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問66・改編】SWOT分析で識別する自社製品に関する外部要因はどれか。','[{"id":"a","text":"営業力における強み"},{"id":"b","text":"機能面における強み"},{"id":"c","text":"新規参入による脅威"},{"id":"d","text":"品質における弱み"}]','"c"','脅威と機会は外部要因、強みと弱みは内部要因。 中文：威胁和机会是外部因素，优势和劣势是内部因素。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q67','exam-fe','ベンチマーキング','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問67・改編】企業経営におけるベンチマーキングの説明はどれか。','[{"id":"a","text":"経営資源の配分を全社的に計画・管理し効率を高める"},{"id":"b","text":"競合や先進企業と製品・サービス・業務を比較し自社戦略の策定に生かす"},{"id":"c","text":"顧客視点で業務プロセスを再設計し企業構造を抜本的に変える"},{"id":"d","text":"他社より優れた自社独自の技術に経営資源を集中する"}]','"b"','優れた他社などと比較して改善・戦略立案に生かすのがベンチマーキング。 中文：基准对标通过与竞争对手或先进企业比较改进自身。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q68','exam-fe','ニッチャ戦略','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問68・改編】競争上のポジションでニッチャの基本戦略はどれか。','[{"id":"a","text":"リーダを追撃するための差別化戦略"},{"id":"b","text":"市場機会に素早く対応する模倣戦略"},{"id":"c","text":"製品や市場を専門特化する特定化戦略"},{"id":"d","text":"全市場をカバーし最大シェアを確保する全方位戦略"}]','"c"','ニッチャは特定の市場や製品に集中し専門性を高める。 中文：利基者聚焦特定市场与产品，发挥专业优势。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q69','exam-fe','オープンイノベーション','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問69・改編】オープンイノベーションに該当する事例はどれか。','[{"id":"a","text":"社外からアイデアを募集し新サービスの開発に活用する"},{"id":"b","text":"社内の製造部と企画部が共同で新製品を開発する"},{"id":"c","text":"物流システムを変更して販売を効率化する"},{"id":"d","text":"自社製品の革新性をWebに掲載してブランドを高める"}]','"a"','社外の知識やアイデアを組み合わせて新しい価値を作る。 中文：开放式创新利用组织外部的知识和创意创造新价值。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q70','exam-fe','RPA','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問70・改編】RPAの説明はどれか。','[{"id":"a","text":"ルールエンジンや認知技術などを使い、ホワイトカラーの単純な間接作業を代行するソフトウェア"},{"id":"b","text":"対象物の把持や移動などをプログラムで行う産業用ロボット"},{"id":"c","text":"周囲を認識し自律走行するためのレーダやGPSなどの機器"},{"id":"d","text":"食事・清掃・移動などの生活支援に使うロボット"}]','"a"','RPAはソフトウェアで定型的な業務操作を自動化する。物理的なロボットとは区別する。 中文：RPA使用软件自动处理规则明确的事务，不是实体机器人。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q72','exam-fe','部品表と所要量','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問72・改編】製品A1個に部品Bが2個、部品Cが1個必要。B1個にはCが1個、Dが1個、Eが1個必要。Aを10個生産する。Bの在庫0個、Cの在庫5個のとき、発注が必要なCは最低何個か。','[{"id":"a","text":"15"},{"id":"b","text":"20"},{"id":"c","text":"25"},{"id":"d","text":"30"}]','"c"','A10個に直接C10個、B20個にC20個必要。計30個から在庫5個を引き25個。 中文：直接需要10个C，20个B另需20个C，减库存5个后采购25个。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q73','exam-fe','CGM','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問73・改編】CGM（Consumer Generated Media）の説明はどれか。','[{"id":"a","text":"オークション形式で消費者同士の個人売買を仲介する"},{"id":"b","text":"個人制作のデジタルコンテンツを閲覧者へ配信し利用者同士で共有できる"},{"id":"c","text":"個人商店のオンラインショップを集めポイント発行や決済を代行する"},{"id":"d","text":"希望する顧客へ電子メールで定期的に情報を配信する"}]','"b"','CGMは利用者が作るコンテンツを共有・発信するメディア。 中文：消费者生成媒体由用户制作并分享内容。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q75','exam-fe','CIO','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問75・改編】CIOの果たすべき役割はどれか。','[{"id":"a","text":"各部門の代表として自部門のシステム化案を情報システム部門に提示する"},{"id":"b","text":"情報技術の調査・利用研究や関連部門への教育を実施する"},{"id":"c","text":"全社的な情報化戦略を立案し経営戦略との整合性を確認・評価する"},{"id":"d","text":"業務経験とIT知識を使い個別プロジェクトの運営を管理する"}]','"c"','CIOは全社の情報戦略を経営戦略と整合させる役割を担う。 中文：首席信息官从全公司角度制定信息战略并确保与经营战略一致。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q76','exam-fe','職能別組織','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問76・改編】経営者の下に、生産・販売・研究開発・経理・人事の各部門を並べた組織構造はどれか。','[{"id":"a","text":"事業部制組織"},{"id":"b","text":"職能別組織"},{"id":"c","text":"プロジェクト組織"},{"id":"d","text":"マトリックス組織"}]','"b"','生産や販売などの機能ごとに部門を分けるのは職能別組織。 中文：按生产、销售、财务等职能划分的是职能型组织。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q77','exam-fe','期待利益','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問77・改編】仕入数ごとの販売数の確率は、4個仕入:4個100%；5個仕入:4個30%、5個70%；6個仕入:4個30%、5個30%、6個40%；7個仕入:4個30%、5個30%、6個30%、7個10%。売れた1個の利益は1,000円、当日売れ残り1個の廃棄ロスは300円。利益の期待値が最大の仕入数は何個か。','[{"id":"a","text":"4"},{"id":"b","text":"5"},{"id":"c","text":"6"},{"id":"d","text":"7"}]','"c"','期待利益は4個:4,000円、5個:4,610円、6個:4,830円、7個:4,660円。最大は6個。 中文：分别计算销量概率与剩余损失，采购6个的期望利润4830日元最高。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q79','exam-fe','ソフトウェア著作権','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問79・改編】著作権法によるソフトウェアの保護範囲について適切なものはどれか。','[{"id":"a","text":"アプリケーションは保護されるがOSなどの基本プログラムは保護されない"},{"id":"b","text":"アルゴリズムやプログラム言語は著作権法で保護される"},{"id":"c","text":"アルゴリズムの文書は保護されるが、それを用いたプログラムは保護されない"},{"id":"d","text":"ソースプログラムとオブジェクトプログラムの両方が保護される"}]','"d"','プログラムはソース形式とオブジェクト形式の双方が著作物として保護され得る。 中文：源程序和目标程序都可以作为程序著作物受到保护。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q80','exam-fe','サイバーセキュリティ基本法','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問80・改編】2021年の試験におけるサイバーセキュリティ基本法の説明として正しいものはどれか。','[{"id":"a","text":"国民は重要性への関心と理解を深め、確保に必要な注意を払うよう努めると規定する"},{"id":"b","text":"国と通信事業者の責務のみで地方公共団体や教育研究機関への言及はない"},{"id":"c","text":"国と地方公共団体の責務のみで民間事業者の努力に関する規定はない"},{"id":"d","text":"地方公共団体を重要社会基盤事業者と定義し関連施策に責任を負わせる"}]','"a"','試験当時の同法は国民の関心・理解と必要な注意に関する努力を規定する。 中文：依该考试当时的法律，国民应努力理解网络安全的重要性并采取必要注意。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption');
